"""Authored StackYoga logical-key adapter; this module is not generated by Microsoft Kiota."""

from __future__ import annotations

from urllib.parse import quote, urlsplit, urlunsplit

from .v1.storage.objects.item.with_key_item_request_builder import WithKeyItemRequestBuilder
from .v1.storage.objects.objects_request_builder import ObjectsRequestBuilder

_RAW_URL_PLACEHOLDER = "_stackyoga_raw_url_"


def build_storage_object_url(gateway_endpoint: str, logical_key: str) -> str:
    """Validate a project-local key and encode each path segment into a raw object URL."""
    _validate_storage_logical_key(logical_key)
    if not isinstance(gateway_endpoint, str):
        raise TypeError("gateway_endpoint must be a string")
    try:
        gateway = urlsplit(gateway_endpoint)
        _ = gateway.port
    except ValueError as exception:
        raise ValueError("gateway_endpoint must be an origin-only HTTP(S) URL") from exception
    if (
        gateway.scheme not in ("https", "http")
        or not gateway.hostname
        or gateway.username is not None
        or gateway.password is not None
        or gateway.path not in ("", "/")
        or gateway.query
        or gateway.fragment
        or any(character.isspace() or ord(character) < 32 for character in gateway.netloc)
    ):
        raise ValueError("gateway_endpoint must be an origin-only HTTP(S) URL")

    encoded_key = "/".join(quote(segment, safe="-._~") for segment in logical_key.split("/"))
    return urlunsplit((gateway.scheme, gateway.netloc, f"/v1/storage/objects/{encoded_key}", "", ""))


def storage_object_for_logical_key(
    objects: ObjectsRequestBuilder,
    gateway_endpoint: str,
    logical_key: str,
) -> WithKeyItemRequestBuilder:
    """Return the generated item builder through its ``with_url`` raw-URL override."""
    if objects is None:
        raise TypeError("objects cannot be null")
    raw_url = build_storage_object_url(gateway_endpoint, logical_key)
    return objects.by_key(_RAW_URL_PLACEHOLDER).with_url(raw_url)


def _validate_storage_logical_key(logical_key: str) -> None:
    if not isinstance(logical_key, str):
        raise TypeError("logical_key must be a string")
    try:
        utf16_length = len(logical_key.encode("utf-16-le")) // 2
    except UnicodeEncodeError as exception:
        raise ValueError("logical_key must contain valid Unicode") from exception
    if (
        utf16_length < 1
        or utf16_length > 1024
        or not logical_key.strip()
        or logical_key.startswith("/")
        or logical_key.startswith("projects/")
        or "://" in logical_key
        or "\\" in logical_key
        or "%" in logical_key
        or "\0" in logical_key
    ):
        raise ValueError("logical_key must be a bounded project-local storage key")
    if any(segment in ("", ".", "..") for segment in logical_key.split("/")):
        raise ValueError("logical_key cannot contain empty, dot, or dot-dot segments")
